#!/usr/bin/env python3
"""
Round 209o (culprits), 15 October 2026. Needs round 208o.

To the Sun; Moon, Mars and Sun views reworked; 3D notes box; land use note.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

NOTES = ["## Round 209o (15 October)\n\nNeeds round 208o (guards on its heading). Tiles patch round209o_tiles.py\n(culprits-tiles-more). No app.js?v= bump.\n\n- To the Sun (Off-planet invasion > From Earth), three rows:\n  - solar_gem: GEM's Global Solar Power Tracker, every phase (CC BY 4.0),\n    tiles/solar_gem.pmtiles, built by gem_solar.py from the owner's download\n    in culprits-tiles-more gem/solar/download/ (GEM gives it by form only);\n  - solar_companies: Wikipedia's List of photovoltaics companies, every\n    company table, at headquarters from Wikidata (solar_companies.py);\n  - sun_objects: GCAT's Heliocentric Register (CC BY), placed by NASA/JPL\n    Horizons (sun.py); opens the new Sun view. A Sun button sits beside\n    Moon and Mars.\n- bodies.html rewritten for the Moon, Mars and the Sun:\n  - stars behind every view; the left box rolls up; Layer colours (presets,\n    wheel, brightness) recolour the marks;\n  - every mark drawn on its own, smaller; a click lists every mark under the\n    pointer; the box opens under the looks box, never over another, and\n    wraps its text (no sideways scrolling);\n  - timeline with two ends;\n  - looks: Satellite, Twilight (was Woodlands), Bioluminescent (now glows),\n    Hologram, Hell (crimson); Jurassic, Atlas and Standard taken off there;\n  - the Sun view: the plane the planets go round in, from above or from the\n    side, in AU; objects Horizons does not follow are listed;\n  - the page is asked as bodies.html?v=209 so browsers fetch the new one.\n- How to move in 3D: opens as a box of its own beside the settings box.\n- Land use: the row says to zoom in while the map is too far out for\n  OpenStreetMap's plots, which only exist in the tiles close in.\n\n"]


DIFF = ""


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("round209o: run from the culprits repository root")
    h = root / "HANDOFF.md"
    if "## Round 208o" not in h.read_text(encoding="utf-8"):
        sys.exit("round209o: round 208o must be applied first")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", path, check=False).returncode == 0:
        print("round209o: already applied")
    else:
        r = git("apply", "--3way", path, check=False)
        if r.returncode != 0:
            git("checkout", "--", "map/app.js", "map/index.html", "map/bodies.html", "map/test.mjs", "map/atlas-plate.webp", check=False)
            sys.exit("round209o: the diff did not apply:\n" + r.stdout + r.stderr)
        print("round209o: applied")
    text = h.read_text(encoding="utf-8")
    add = "".join(n if n.endswith("\n\n") else n.rstrip("\n") + "\n\n" for n in NOTES if n.split("\n", 1)[0] not in text)
    if add:
        at = text.index("\n## Round ") + 1
        h.write_text(text[:at] + add + text[at:], encoding="utf-8")


if __name__ == "__main__":
    main()
